(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-588":{scenario:{company:"Tân Phong Calibration Lab",supervisor:{name:"Đỗ Minh Khoa",role:{vi:"Trưởng phòng thí nghiệm hiệu chuẩn",en:"Calibration Laboratory Manager"}},ref_code:"CAL-5521",title:{vi:"Đo đúng. Tính đủ. Kết luận trung thực.",en:"Measure right. Count every uncertainty. Report honestly."},brief:{vi:"Bạn soát xét giấy chứng nhận hiệu chuẩn nháp CAL-5521 cho đồng hồ áp suất 0-16 bar, cấp chính xác 1.0 (MPE ±0,16 bar). Tại điểm 10 bar, sai số đo được là +0,14 bar. Ngân sách độ không đảm bảo chuẩn gồm: chuẩn 0,012 bar, độ phân giải 0,009 bar, độ lặp lại 0,008 bar. Hợp đồng áp dụng quy tắc quyết định có băng bảo vệ w = U. Hãy sửa U và kết luận phù hợp, rồi lập báo cáo có căn cứ.",en:"You are reviewing draft calibration certificate CAL-5521 for a 0-16 bar pressure gauge, accuracy class 1.0 (MPE ±0.16 bar). At the 10 bar point the measured error is +0.14 bar. The standard uncertainty budget holds 0.012 bar (reference), 0.009 bar (resolution) and 0.008 bar (repeatability). The contract applies a guard-banded decision rule with w = U. Correct U and the conformity statement, then write an evidence-based report."},reference_title:{vi:"Ngân sách độ không đảm bảo đo & quy tắc quyết định đã duyệt",en:"Approved uncertainty budget & decision rule"},fields:[{id:"VERDICT",label:{vi:"Kết luận phù hợp tại 10 bar",en:"Conformity statement at 10 bar"},initial:"PASS",expected:"FAIL",choices:["PASS","FAIL","CONDITIONAL"],reference:"Quy tắc quyết định của hợp đồng",ref_value:{vi:"Băng bảo vệ w = U; giới hạn chấp nhận = MPE - U; MPE ±0,16 bar",en:"Guard band w = U; acceptance limit = MPE - U; MPE ±0.16 bar"},hint:{vi:"So sánh |sai số| với giới hạn chấp nhận đã trừ băng bảo vệ, không so trực tiếp với MPE.",en:"Compare |error| with the guard-banded acceptance limit, not directly with the MPE."}},{id:"U_EXP",label:{vi:"Độ không đảm bảo đo mở rộng U (bar)",en:"Expanded uncertainty U (bar)"},initial:"0.017",expected:"0.034",reference:"Bảng ngân sách độ không đảm bảo đo",ref_value:{vi:"u chuẩn 0,012; u phân giải 0,009; u lặp lại 0,008 bar; hệ số phủ k = 2",en:"u reference 0.012; u resolution 0.009; u repeatability 0.008 bar; coverage factor k = 2"},hint:{vi:"Bản nháp mới dừng ở độ không đảm bảo chuẩn tổng hợp u_c, còn thiếu một bước của SOP 3.2.",en:"The draft stops at the combined standard uncertainty u_c; one step of SOP 3.2 is missing."}}],sop32:{vi:"u_c = căn bậc hai của tổng bình phương các độ không đảm bảo chuẩn thành phần; U = k x u_c với k = 2 (mức tin cậy khoảng 95%); ghi U đến 0,001 bar.",en:"u_c = square root of the sum of squares of the standard uncertainty components; U = k x u_c with k = 2 (about 95% coverage); state U to 0.001 bar."},context:{label:"LIMS / CAL-5521",metrics:[{label:{vi:"Dải đo",en:"Range"},value:"0-16 bar"},{label:{vi:"MPE cấp 1.0",en:"Class 1.0 MPE"},value:"±0.16 bar"},{label:{vi:"Sai số tại 10 bar",en:"Error at 10 bar"},value:"+0.14 bar"}]},crisis:{vi:"Khách hàng gọi: “Mai đánh giá ISO 9001 rồi, sai số 0,14 vẫn nhỏ hơn 0,16 mà. Ghi PASS giúp anh, không thì anh chuyển sang phòng thí nghiệm khác.” Trưởng nhóm kinh doanh nhắn bạn phát hành ngay.",en:"The customer calls: “Our ISO 9001 audit is tomorrow and 0.14 is still below 0.16. Just mark it PASS or we move to another lab.” The sales lead texts you to issue the certificate now."},options:{safe:{vi:"Giữ kết luận FAIL theo quy tắc quyết định đã thỏa thuận, ghi rõ U, báo trưởng phòng; đề xuất hiệu chỉnh đồng hồ rồi hiệu chuẩn lại, ghi số liệu trước và sau hiệu chỉnh.",en:"Keep the FAIL statement under the agreed decision rule, state U and inform the lab manager; offer to adjust the gauge and recalibrate, reporting as-found and as-left data."},shortcut:{vi:"Ghi PASS theo yêu cầu khách hàng vì sai số vẫn nằm trong MPE, bỏ qua băng bảo vệ.",en:"Mark PASS as the customer asks because the error is within the MPE, ignoring the guard band."},wait:{vi:"Giữ chứng nhận ở trạng thái nháp và chờ kinh doanh tự thương lượng với khách hàng.",en:"Leave the certificate in draft and wait for Sales to negotiate with the customer."}},questions:{vi:["Trình bày cách bạn tính lại U và vì sao sai số +0,14 bar dẫn tới kết luận FAIL theo quy tắc w = U.","Khi khách hàng gây áp lực đổi kết luận, bạn bảo vệ tính khách quan của phòng thí nghiệm theo ISO/IEC 17025 như thế nào?"],en:["Explain how you recalculated U and why the +0.14 bar error leads to a FAIL statement under the w = U rule.","When the customer pressures you to change the statement, how do you protect laboratory impartiality under ISO/IEC 17025?"]},hints:{vi:["Đặt bản nháp cạnh ngân sách độ không đảm bảo đo và kiểm tra từng thành phần đã được tổ hợp đúng cách chưa.","Theo SOP mục 3.2, có u_c rồi vẫn phải nhân hệ số phủ trước khi tính giới hạn chấp nhận.","SOP mục 4.2: kết luận phù hợp không thay đổi theo yêu cầu thương mại; mọi áp lực phải báo trưởng phòng."],en:["Place the draft next to the uncertainty budget and check that every component is combined correctly.","Under SOP 3.2, once you have u_c you still apply the coverage factor before computing the acceptance limit.","SOP 4.2: a conformity statement never changes for commercial reasons; escalate any pressure to the lab manager."]}},learning:{summary:{vi:"Kỹ thuật viên đo lường và hiệu chuẩn so sánh phương tiện đo của doanh nghiệp với chuẩn có liên kết chuẩn đo lường, xác định sai số, ước lượng độ không đảm bảo đo và phát hành giấy chứng nhận hiệu chuẩn. Kết quả của họ quyết định thiết bị có tiếp tục được dùng trong sản xuất, kiểm tra chất lượng và an toàn hay không. Nghề đòi hỏi thao tác cẩn thận, kiểm soát môi trường đo, nắm vững thống kê đo lường và giữ tính khách quan tuyệt đối.",en:"A metrology and calibration technician compares a company's measuring instruments with traceable reference standards, determines errors, evaluates measurement uncertainty and issues calibration certificates. Their results decide whether equipment may remain in use for production, quality control and safety. The role requires careful handling, control of the measuring environment, solid measurement statistics and uncompromising impartiality."},responsibilities:{vi:["Hiệu chuẩn phương tiện đo áp suất, nhiệt độ, khối lượng, kích thước theo quy trình đã phê duyệt.","Kiểm soát điều kiện môi trường (nhiệt độ, độ ẩm, rung) và thời gian ổn định thiết bị trước khi đo.","Ước lượng độ không đảm bảo đo theo GUM và áp dụng quy tắc quyết định khi công bố sự phù hợp.","Lập, soát xét và lưu hồ sơ giấy chứng nhận, bảo đảm truy xuất nguồn gốc đến chuẩn quốc gia.","Quản lý lịch hiệu chuẩn, kiểm tra trung gian chuẩn làm việc và tham gia thử nghiệm thành thạo."],en:["Calibrate pressure, temperature, mass and dimensional instruments to approved procedures.","Control environmental conditions (temperature, humidity, vibration) and stabilization time before measuring.","Evaluate measurement uncertainty per the GUM and apply decision rules when stating conformity.","Prepare, review and archive certificates, ensuring traceability to national standards.","Manage the calibration schedule, run intermediate checks on working standards and join proficiency tests."]},competencies:[{name:{vi:"Thao tác đo chính xác",en:"Precise measurement practice"},desc:{vi:"Lắp đặt, ổn định và đọc số đúng cách; loại trừ sai số thị sai, sai số do nhiệt và do lắp đặt.",en:"Mount, stabilize and read instruments correctly; eliminate parallax, thermal and mounting errors."}},{name:{vi:"Ước lượng độ không đảm bảo đo",en:"Uncertainty evaluation"},desc:{vi:"Xây dựng ngân sách độ không đảm bảo loại A, loại B, tổ hợp và chọn hệ số phủ phù hợp.",en:"Build Type A and Type B uncertainty budgets, combine them and choose the right coverage factor."}},{name:{vi:"Quy tắc quyết định",en:"Decision rules"},desc:{vi:"Áp dụng chấp nhận đơn giản hoặc băng bảo vệ theo thỏa thuận với khách hàng và hướng dẫn ILAC-G8.",en:"Apply simple acceptance or guard bands as agreed with the customer and per ILAC-G8 guidance."}},{name:{vi:"Hệ thống chất lượng phòng thí nghiệm",en:"Laboratory quality system"},desc:{vi:"Tuân thủ ISO/IEC 17025: kiểm soát hồ sơ, xác nhận phương pháp, xử lý công việc không phù hợp.",en:"Follow ISO/IEC 17025: control records, validate methods and handle nonconforming work."}},{name:{vi:"Khách quan & chính trực",en:"Impartiality & integrity"},desc:{vi:"Không để áp lực thương mại chi phối kết quả; báo cáo trung thực cả khi thiết bị không đạt.",en:"Never let commercial pressure influence results; report honestly even when equipment fails."}}],knowledge:{vi:["ISO/IEC 17025:2017 - Yêu cầu chung về năng lực của phòng thử nghiệm và hiệu chuẩn.","Luật Đo lường số 04/2011/QH13 và các văn bản hướng dẫn về chuẩn đo lường, phương tiện đo.","JCGM 100:2008 (GUM) - Hướng dẫn biểu thị độ không đảm bảo đo.","JCGM 200:2012 (VIM) - Từ vựng quốc tế về đo lường học: sai số, độ chụm, liên kết chuẩn.","ILAC-G8:09/2019 - Hướng dẫn về quy tắc quyết định và công bố sự phù hợp.","ISO 10012:2003 - Hệ thống quản lý đo lường cho quá trình đo và thiết bị đo."],en:["ISO/IEC 17025:2017 - General requirements for the competence of testing and calibration laboratories.","Vietnam's Law on Metrology No. 04/2011/QH13 and its guidance on standards and measuring instruments.","JCGM 100:2008 (GUM) - Guide to the expression of uncertainty in measurement.","JCGM 200:2012 (VIM) - International vocabulary of metrology: error, precision, traceability.","ILAC-G8:09/2019 - Guidelines on decision rules and statements of conformity.","ISO 10012:2003 - Measurement management systems for measurement processes and equipment."]},tools:["Bộ hiệu chuẩn áp suất điện tử","Cân piston (dead-weight tester)","Lò hiệu chuẩn nhiệt độ khô","Bộ căn mẫu chuẩn (gauge block)","Phần mềm quản lý phòng thí nghiệm (LIMS)","Bảng tính ngân sách độ không đảm bảo đo"],kpis:{vi:["Tỷ lệ giấy chứng nhận phát hành đúng hạn cam kết.","Số giấy chứng nhận phải thu hồi hoặc sửa do lỗi (mục tiêu bằng 0).","Kết quả thử nghiệm thành thạo đạt |En| <= 1.","Tỷ lệ chuẩn làm việc được kiểm tra trung gian đúng kế hoạch."],en:["Share of certificates issued by the committed date.","Certificates recalled or corrected due to errors (target zero).","Proficiency test results with |En| <= 1.","Share of working standards given intermediate checks on schedule."]},day:[{time:"08:00",vi:"Ghi nhận nhiệt độ, độ ẩm phòng đo; khởi động và ổn định chuẩn làm việc.",en:"Log room temperature and humidity; power up and stabilize the working standards."},{time:"09:00",vi:"Hiệu chuẩn lô đồng hồ áp suất theo chu trình tăng và giảm áp, ghi số liệu thô.",en:"Calibrate a batch of pressure gauges on rising and falling cycles and record raw data."},{time:"11:00",vi:"Tính sai số, độ không đảm bảo đo và áp dụng quy tắc quyết định đã thỏa thuận.",en:"Compute errors and uncertainty and apply the agreed decision rule."},{time:"14:00",vi:"Kiểm tra trung gian chuẩn làm việc bằng chuẩn đối chứng, cập nhật biểu đồ kiểm soát.",en:"Run intermediate checks on working standards against a check standard and update control charts."},{time:"16:30",vi:"Soát xét chéo giấy chứng nhận, lưu hồ sơ trên LIMS và trả lời khách hàng.",en:"Peer-review certificates, archive records in the LIMS and answer customers."}],mistakes:{vi:["Báo cáo độ không đảm bảo chuẩn tổng hợp mà quên nhân hệ số phủ k.","Kết luận PASS chỉ vì sai số nhỏ hơn MPE, bỏ qua độ không đảm bảo và quy tắc quyết định.","Đo khi thiết bị chưa ổn định nhiệt hoặc không ghi điều kiện môi trường vào hồ sơ."],en:["Reporting the combined standard uncertainty without applying the coverage factor k.","Stating PASS only because the error is below the MPE, ignoring uncertainty and the decision rule.","Measuring before thermal stabilization or without recording environmental conditions."]},career:[{vi:"Kỹ thuật viên hiệu chuẩn tập sự",en:"Trainee calibration technician"},{vi:"Kỹ thuật viên đo lường & hiệu chuẩn",en:"Metrology & calibration technician"},{vi:"Kỹ sư đo lường, người ký giấy chứng nhận",en:"Metrology engineer and authorized signatory"},{vi:"Trưởng phòng thí nghiệm hiệu chuẩn",en:"Calibration laboratory manager"}],glossary:[{term:"Traceability",vi:"Tính chất của kết quả đo liên hệ được với chuẩn quốc gia hoặc quốc tế qua chuỗi hiệu chuẩn không đứt đoạn, mỗi bước có độ không đảm bảo xác định.",en:"Property of a result that relates to national or international standards through an unbroken calibration chain, each step with stated uncertainty."},{term:"MPE",vi:"Sai số lớn nhất cho phép của phương tiện đo theo cấp chính xác hoặc quy định kỹ thuật.",en:"Maximum permissible error of an instrument set by its accuracy class or specification."},{term:"Expanded uncertainty U",vi:"Độ không đảm bảo chuẩn tổng hợp nhân hệ số phủ k, cho khoảng chứa giá trị đo với xác suất phủ đã nêu.",en:"Combined standard uncertainty multiplied by a coverage factor k, giving an interval with a stated coverage probability."},{term:"Guard band",vi:"Khoảng trừ vào giới hạn dung sai để giảm rủi ro chấp nhận nhầm thiết bị không đạt.",en:"Margin subtracted from a tolerance limit to reduce the risk of falsely accepting a nonconforming item."},{term:"TUR",vi:"Tỷ số giữa dung sai của phương tiện được hiệu chuẩn và độ không đảm bảo của phép hiệu chuẩn; thường yêu cầu tối thiểu 4:1.",en:"Ratio of the tolerance of the unit under test to the calibration uncertainty; at least 4:1 is commonly required."}],quiz:[{q:{vi:"Độ không đảm bảo chuẩn tổng hợp u_c = 0,015 bar, hệ số phủ k = 2. Độ không đảm bảo mở rộng U là bao nhiêu?",en:"The combined standard uncertainty is u_c = 0.015 bar and the coverage factor k = 2. What is the expanded uncertainty U?"},options:{vi:["0,015 bar","0,030 bar","0,0075 bar","0,225 bar"],en:["0.015 bar","0.030 bar","0.0075 bar","0.225 bar"]},answer:1,explain:{vi:"U = k x u_c = 2 x 0,015 = 0,030 bar, tương ứng mức tin cậy khoảng 95%.",en:"U = k x u_c = 2 x 0.015 = 0.030 bar, corresponding to about 95% coverage."}},{q:{vi:"Theo ISO/IEC 17025:2017, khi công bố sự phù hợp với quy định kỹ thuật, phòng thí nghiệm phải làm gì?",en:"Under ISO/IEC 17025:2017, what must a laboratory do when it issues a statement of conformity to a specification?"},options:{vi:["Chỉ cần ghi sai số đo được","Không cần nêu thêm thông tin nào","Dùng quy tắc khách hàng đề nghị qua điện thoại","Lập văn bản quy tắc quyết định đã áp dụng, có tính đến mức rủi ro"],en:["Only record the measured error","Add no further information","Use whatever rule the customer suggests by phone","Document the decision rule applied, taking the level of risk into account"]},answer:3,explain:{vi:"Chuẩn mực yêu cầu quy tắc quyết định được thỏa thuận, lập thành văn bản và tính đến rủi ro chấp nhận hoặc loại bỏ sai.",en:"The standard requires an agreed, documented decision rule that accounts for the risk of false acceptance or rejection."}},{q:{vi:"Khách hàng đề nghị ghi PASS dù thiết bị không đạt theo quy tắc quyết định. Bạn làm gì?",en:"A customer asks you to state PASS although the instrument fails under the decision rule. What do you do?"},options:{vi:["Giữ kết luận đúng, báo trưởng phòng và đề xuất hiệu chỉnh rồi hiệu chuẩn lại","Ghi PASS kèm chú thích nhỏ cuối trang","Xóa điểm đo không đạt khỏi chứng nhận","Trả thiết bị không có chứng nhận và không giải thích"],en:["Keep the correct statement, inform the manager and offer adjustment and recalibration","Write PASS with a small footnote","Delete the failing point from the certificate","Return the instrument with no certificate or explanation"]},answer:0,explain:{vi:"Tính khách quan là yêu cầu bắt buộc; phương án hợp lệ là hiệu chỉnh thiết bị và ghi cả số liệu trước, sau hiệu chỉnh.",en:"Impartiality is mandatory; the valid path is to adjust the instrument and report both as-found and as-left data."}},{q:{vi:"Dung sai của đồng hồ là ±0,16 bar, độ không đảm bảo mở rộng của phép hiệu chuẩn là 0,04 bar. TUR là bao nhiêu?",en:"The gauge tolerance is ±0.16 bar and the calibration expanded uncertainty is 0.04 bar. What is the TUR?"},options:{vi:["2:1","8:1","4:1","16:1"],en:["2:1","8:1","4:1","16:1"]},answer:2,explain:{vi:"TUR = 0,16 / 0,04 = 4:1, vừa đạt mức tối thiểu thường được yêu cầu.",en:"TUR = 0.16 / 0.04 = 4:1, just meeting the commonly required minimum."}}],tools_en:["Electronic pressure calibrator","Piston gauge (dead-weight tester)","Dry-block temperature calibrator","Gauge block set","Laboratory information management system (LIMS)","Measurement uncertainty budget spreadsheet"]}}})})(window.KKR);
